  planSource.mockImplementation(() => ({ name: 'plan', lexical: stalled, embedding: stalled }));
  const row = hit({ source: 'doc', source_id: 'harness:papercusp:repair',
    excerpt: 'http2 transport repair prerequisite: keep snapshot', score: 1,
    meta: { section: 'Repair' } });
